import random
from lrucache import LRUCache
class Ref:
    def __init__(s,cap): s.cap=cap; s.order=[]; s.vals={}
    def touch(s,k): s.order.remove(k); s.order.append(k)
    def get(s,k,d=None):
        if k not in s.vals: return d
        s.touch(k); return s.vals[k]
    def put(s,k,v):
        if k in s.vals: s.vals[k]=v; s.touch(k); return
        if len(s.vals)>=s.cap: old=s.order.pop(0); del s.vals[old]
        s.vals[k]=v; s.order.append(k)
